    b+='<rect x="132" y="92" width="45" height="45" fill="#8aa" stroke="#555"/><rect x="185" y="92" width="45" height="45" fill="#9a8" stroke="#555"/><rect x="238" y="92" width="45" height="45" fill="#aab" stroke="#555"/>'
