    b+='<rect x="368" y="70" width="100" height="90" fill="#5a4a8a" stroke="#555"/>'+T(380,185,'Blank Database',10,'start',700)+T(380,200,'File Name',8,'start',700)+'<rect x="378" y="205" width="90" height="12" fill="#fff" stroke="#666"/>'+T(385,215,'Database1',7,'start',400)
